    seen=[[False]*W for _ in range(H)]; bars=[]; dots=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and not seen[r][c]:
                col=I[r][c]; cells=[(r,c)]; stack=[(r,c)]
                while stack:
                    rr,cc=stack.pop()
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and I[nr][nc]==col:
                            seen[nr][nc]=True; cells.append((nr,nc)); stack.append((nr,nc))
                if len(cells)==1:
                    dots.append((r,c,col))
