                    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                    if len(set(rs))==1: bars.append(('H',col,rs[0],min(cs),max(cs)))
                    elif len(set(cs))==1: bars.append(('V',col,min(rs),min(cs),max(rs)))
