            v=I[rr][cc]
            if v!=bg:
                if (rr,cc) in [(d[0],d[1]) for d in dots]:
                    O[rr][cc]=4
                return
            O[rr][cc]=next(d[2] for d in dots) if dots else None
            rr+=dr; cc+=dc
    for br in bars:
        orient,bcol,s,_a,_b_=br
        if orient=='H':
            for c in range(_a,_b_+1):
                for dr in (1,-1):
                    trace(br,bcol,s,c,dr,0)
